import io
import unittest

import tomli


class TestInlineTableTOML11(unittest.TestCase):
    def test_newlines_without_trailing_comma(self):
        self.assertEqual(
            tomli.loads('t = {\n\tfirst = 1\n,\n second = "two"\n}\nafter = true'),
            {"t": {"first": 1, "second": "two"}, "after": True},
        )

    def test_single_line_trailing_comma(self):
        self.assertEqual(tomli.loads("t = {a = 1,}"), {"t": {"a": 1}})

    def test_nested_tables_and_dotted_keys(self):
        self.assertEqual(
            tomli.loads("t = {\n a.b = 1,\n a.c = {\n x = 2,\n },\n items = [{\n y = 3,\n },],\n}"),
            {"t": {"a": {"b": 1, "c": {"x": 2}}, "items": [{"y": 3}]}},
        )

    def test_empty_multiline_table(self):
        self.assertEqual(tomli.loads("t = {\n \t\n}"), {"t": {}})

    def test_comments_between_entries(self):
        self.assertEqual(
            tomli.loads("t = {# opening\n # before key\n a = '# value', # after comma\n b = 2 # before comma\n , # trailing\n # before close\n}"),
            {"t": {"a": "# value", "b": 2}},
        )

    def test_crlf_binary_load(self):
        self.assertEqual(
            tomli.load(io.BytesIO(b"t = {\r\n a = 1,\r\n}\r\nafter = 2")),
            {"t": {"a": 1}, "after": 2},
        )

    def test_missing_comma_is_invalid(self):
        with self.assertRaises(tomli.TOMLDecodeError):
            tomli.loads("t = {\n a = 1\n b = 2\n}")

    def test_double_comma_is_invalid(self):
        with self.assertRaises(tomli.TOMLDecodeError):
            tomli.loads("t = {\n a = 1,\n ,\n}")

    def test_empty_table_comma_is_invalid(self):
        with self.assertRaises(tomli.TOMLDecodeError):
            tomli.loads("t = {\n ,\n}")

    def test_unclosed_table_is_invalid(self):
        with self.assertRaises(tomli.TOMLDecodeError):
            tomli.loads("t = {\n a = 1,\n")

    def test_duplicate_key_is_invalid(self):
        with self.assertRaises(tomli.TOMLDecodeError):
            tomli.loads("t = {\n a = 1,\n a = 2,\n}")

    def test_nested_table_remains_immutable(self):
        with self.assertRaises(tomli.TOMLDecodeError):
            tomli.loads("t = {\n a = {\n b = 1,\n },\n a.c = 2,\n}")
